public class BeautyShopModule : EntityModule {
  public BeautyShopModule() : base("BeautyShopModule", new Version(1, 0)) {
    RegisterEntities(typeof(IAddress), typeof(IAppointment), typeof(IAppointmentService),
      typeof(IAvailability), typeof(ICompany), typeof(ICustomer), typeof(IEmployee), typeof(IPayment),
      typeof(IPaymentSource), typeof(IPayrollLine), typeof(IPayrollRun), typeof(IPerson), typeof(IPhone),
      typeof(IProduct), typeof(IProductCategory), typeof(ISale), typeof(ISaleLine), typeof(IService),
      typeof(IServiceCategory), typeof(IServiceStation), typeof(IShipment), typeof(IShipmentLine),
      typeof(IShop), typeof(IShopEmployee), typeof(IShopHours), typeof(IStockLevel), typeof(ITenant),
      typeof(ITimeEntry), typeof(IUser), typeof(IVendor), typeof(IVendorInvoice), typeof(IVendorPayment));
    RegisterView<IMvLowStock>(DbServerKind.Postgres, ViewDefinitions.MvLowStockSql);
    RegisterView<IVStylistRevenue>(DbServerKind.Postgres, ViewDefinitions.VStylistRevenueSql);
    RegisterView<IVUpcomingAppointments>(DbServerKind.Postgres, ViewDefinitions.VUpcomingAppointmentsSql);
  }
}

public class BeautyShopApp : EntityApp {
  public BeautyShopApp() : base("BeautyShopApp", new Version(1, 0), new EntityAppSettings { DefaultSchema = "beauty" }) {
    AddModule(new BeautyShopModule(), "beauty");
  }
}

/// <summary>The views' defining selects, as the Postgres server reported them.</summary>
static class ViewDefinitions {
  public const string MvLowStockSql = """
    SELECT t0."Id",
        t0."Tenant_Id" AS "TenantId",
        t1."Name" AS "ShopName",
        t2."Sku",
        t2."Name" AS "ProductName",
        t0."QuantityOnHand",
        t0."ReorderLevel"
       FROM ((beauty."StockLevel" t0
         JOIN beauty."Shop" t1 ON ((t0."Shop_Id" = t1."Id")))
         JOIN beauty."Product" t2 ON ((t0."Product_Id" = t2."Id")))
      WHERE (t0."QuantityOnHand" <= t0."ReorderLevel")
    """;

  public const string VStylistRevenueSql = """
    SELECT t0."Id" AS "EmployeeId",
        t0."Tenant_Id" AS "TenantId",
        (((t1."FirstName")::text || ' '::text) || (t1."LastName")::text) AS "StylistName",
        t2."Name" AS "HomeShopName",
        ( SELECT count(*) AS count
               FROM beauty."Appointment" t3
              WHERE ((t3."Employee_Id" = t0."Id") AND (t3."Status" = 3))) AS "AppointmentCount",
        COALESCE(( SELECT sum((t4."UnitPrice" * (t4."Quantity")::numeric)) AS sum
               FROM beauty."SaleLine" t4
              WHERE (t4."PerformedBy_Id" = t0."Id")), (0)::numeric) AS "RevenueAmount",
        ((COALESCE(( SELECT sum((t5."UnitPrice" * (t5."Quantity")::numeric)) AS sum
               FROM beauty."SaleLine" t5
              WHERE (t5."PerformedBy_Id" = t0."Id")), (0)::numeric) * t0."CommissionPercent") / (100)::numeric) AS "CommissionAmount"
       FROM ((beauty."Employee" t0
         JOIN beauty."Person" t1 ON ((t0."Person_Id" = t1."Id")))
         LEFT JOIN beauty."Shop" t2 ON ((t0."HomeShop_Id" = t2."Id")))
    """;

  public const string VUpcomingAppointmentsSql = """
    SELECT t0."Id" AS "AppointmentId",
        t0."Tenant_Id" AS "TenantId",
        t2."Name" AS "CompanyName",
        t1."Name" AS "ShopName",
        t0."StartsOn",
        t0."EndsOn",
        t0."Status",
        (((t4."FirstName")::text || ' '::text) || (t4."LastName")::text) AS "CustomerName",
        (((t6."FirstName")::text || ' '::text) || (t6."LastName")::text) AS "StylistName",
        COALESCE(( SELECT sum(t7."Price") AS sum
               FROM beauty."AppointmentService" t7
              WHERE (t7."Appointment_Id" = t0."Id")), (0)::numeric) AS "BookedValue"
       FROM ((((((beauty."Appointment" t0
         JOIN beauty."Shop" t1 ON ((t0."Shop_Id" = t1."Id")))
         JOIN beauty."Company" t2 ON ((t1."Company_Id" = t2."Id")))
         JOIN beauty."Customer" t3 ON ((t0."Customer_Id" = t3."Id")))
         JOIN beauty."Person" t4 ON ((t3."Person_Id" = t4."Id")))
         JOIN beauty."Employee" t5 ON ((t0."Employee_Id" = t5."Id")))
         JOIN beauty."Person" t6 ON ((t5."Person_Id" = t6."Id")))
      WHERE ((t0."Status" = 0) OR (t0."Status" = 1) OR (t0."Status" = 2))
    """;
}
